import {createResourcePricer,resourceLibrary,resourceIdentity,refreshProjectResources,isAssemblyPriceReference} from './resource-pricing.js';
import {norm,unitNorm} from './calc.js';
export function setupResourcePricing(api){
 const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>Number(n).toLocaleString('ko-KR');
 document.querySelector('#estToolsDialog .tool-menu').insertAdjacentHTML('beforeend','<button class="button" id="resourcePricesBtn">노임·자재·장비 기준 / 재계산</button>');
 document.body.insertAdjacentHTML('beforeend',`<dialog id="resourcePricesDialog" class="auto-link-dialog"><div class="dialog-head"><div><h2>노임·자재·장비 기준 / 재계산</h2><p>직접 자재는 선택한 DB 단가를 쓰고, 산출식 안의 노임·자재·연료·장비 기준가격은 아래 기준 DB로 계산합니다.</p></div><button class="icon-btn" id="resourcePricesClose" aria-label="닫기">×</button></div><div class="auto-link-controls"><label>노임·자재·장비 기준 DB <select id="resourcePricesLibrary"></select></label><strong id="resourcePricesCount"></strong></div><p class="auto-priority-note">장비 기준가격과 환율까지 기준 DB에서 가져옵니다. 투입량·손료계수·잡품률 등 산식과 별도 수수료는 산출 DB 기준을 유지합니다. 산출식의 노임은 기준 DB에서만 적용하며, 찾지 못한 노임은 기존 단가를 쓰지 않고 미확정으로 표시합니다. 자재·연료·장비에 한해 기존 단가 유지 설정을 적용합니다. 노임 기준이 미확정이거나 산식 검증에 실패한 항목은 합계에서 제외합니다.</p><div class="auto-link-results"><table><thead><tr><th>내역</th><th>기존 단가</th><th>재계산 단가</th><th>변경 근거 / 확인할 항목</th></tr></thead><tbody id="resourcePricesRows"></tbody></table></div><div class="dialog-actions"><button class="button" id="resourcePricesCancel">취소</button><button class="button primary" id="resourcePricesApply">기준 저장 · 내역에 반영</button></div></dialog><dialog id="resourceMappingDialog" class="auto-link-dialog"><div class="dialog-head"><div><h2>기준 DB의 대응 품목 선택</h2><p id="resourceMappingOrigin"></p></div><button class="icon-btn" id="resourceMappingClose" aria-label="닫기">×</button></div><div class="auto-link-controls"><input id="resourceMappingSearch" type="search" placeholder="품명 또는 규격 검색" aria-label="대응 단가 검색"></div><p class="auto-priority-note">같은 단위의 후보만 표시합니다. 지역·재질·규격을 확인하고 선택하세요. 선택한 대응 관계는 이 작업에 저장됩니다.</p><div id="resourceMappingResults" class="auto-link-results"></div></dialog>`);
 let draft,baseline,pending,issues=[],mappingIssue,candidates=[];
 function preview(){const id=$('resourcePricesLibrary').value,lib=api.getLibraries().find(l=>l.id===id);if(!lib){pending=null;$('resourcePricesRows').innerHTML='';$('resourcePricesCount').textContent='노임 기준 DB를 선택하세요.';return;}draft.resourcePriceLibrary={id:lib.id,name:lib.name};pending=refreshProjectResources(draft,api.getLibraries());issues=[];
  const ready=pending.rows.filter(r=>r.ready).length;$('resourcePricesCount').textContent=`재계산 ${ready}행 · 확인 필요 ${pending.rows.length-ready}행`;
  $('resourcePricesRows').innerHTML=pending.rows.map(r=>`<tr><td>${esc(r.name)}</td><td class="number">${num(r.before)}</td><td class="number">${r.ready?num(r.after):'<strong class="error-text">미확정</strong>'}</td><td>${r.issues.length?r.issues.map(i=>{const n=issues.push(i)-1;return `<p class="error-text">${esc(i.resource?.name||'')} ${esc(i.resource?.spec||'')} · ${esc(i.reason)} ${i.resource?`<button class="button small" data-resource-map="${n}">대응 품목 선택</button>`:''}</p>`;}).join(''):(r.changes?.length?`<details><summary>${r.changes.length}개 노임·자재·장비 적용</summary>${r.changes.map(c=>`<p>${esc(c.name)} ${esc(c.spec)}: ${num(c.before)} → ${num(c.after)}${esc(c.currency||'원')}${c.exchangeRate!=null?' · 환율 '+num(c.exchangeRate):''}</p>`).join('')}</details>`:r.mode==='direct-material'?'직접 자재 · 선택 DB 단가 유지':'별도 경비·수수료 유지')}</td></tr>`).join('');
 }
 function mappingSearch(){const pricer=createResourcePricer(draft,api.getLibraries()),r=mappingIssue.resource,tokens=$('resourceMappingSearch').value.split(/\s+/).map(norm).filter(Boolean),cat=r.category==='장비'||r.code?.startsWith('E')?'장비':r.category==='노임'||r.code?.startsWith('L')?'노임':'자재';
  candidates=pricer.resources.filter(c=>c.category===cat&&unitNorm(c.unit)===unitNorm(r.unit)&&tokens.every(t=>norm(c.name+' '+c.spec+' '+c.code).includes(t))).slice(0,80);
  $('resourceMappingResults').innerHTML='<table><thead><tr><th>품명</th><th>규격</th><th>단위</th><th>기준 단가</th><th>선택</th></tr></thead><tbody>'+candidates.map((c,i)=>`<tr><td>${esc(c.name)}</td><td>${esc(c.spec)}</td><td>${esc(c.unit)}</td><td class="number">${num(c.total)}</td><td><button class="button small" data-resource-pick="${i}">이 품목 사용</button></td></tr>`).join('')+'</tbody></table>'+(candidates.length?'':'<p>일치하는 후보가 없습니다. 검색어를 줄여보세요.</p>');
 }
 $('resourcePricesRows').onclick=e=>{const b=e.target.closest('[data-resource-map]');if(!b)return;mappingIssue=issues[Number(b.dataset.resourceMap)];$('resourceMappingOrigin').textContent=`산출 구성: ${mappingIssue.resource.name} / ${mappingIssue.resource.spec||'규격 없음'} / ${mappingIssue.resource.unit}`;$('resourceMappingSearch').value=mappingIssue.resource.name;mappingSearch();$('resourceMappingDialog').showModal();};
 $('resourceMappingSearch').oninput=mappingSearch;
 $('resourceMappingResults').onclick=e=>{const b=e.target.closest('[data-resource-pick]');if(!b)return;const c=candidates[Number(b.dataset.resourcePick)];draft.resourceMappings??={};draft.resourceMappings[resourceIdentity(mappingIssue.resource)]={master:pending.master.name,code:c.code,name:c.name,spec:c.spec,unit:c.unit};$('resourceMappingDialog').close();preview();};
 $('resourceMappingClose').onclick=()=>$('resourceMappingDialog').close();
 $('resourcePricesLibrary').onchange=preview;
 $('resourcePricesClose').onclick=$('resourcePricesCancel').onclick=()=>$('resourcePricesDialog').close();
 $('resourcePricesApply').onclick=()=>{try{if(JSON.stringify(api.getProject())!==baseline)throw Error('내역이 바뀌었습니다. 창을 닫고 다시 검토하세요.');if(!pending)throw Error('노임·자재·장비 기준 DB를 선택하세요.');api.replaceProject(pending.project);$('resourcePricesDialog').close();api.toast(`노임·자재·장비 기준 적용 · 기존 단가 유지 ${pending.rows.filter(r=>r.ready&&r.issues.length).length}행 · 확인 필요 ${pending.rows.filter(r=>!r.ready).length}행`);}catch(e){api.toast(e.message);}};
 function open(){draft=structuredClone(api.getProject());baseline=JSON.stringify(api.getProject());pending=null;$('resourcePricesLibrary').innerHTML='<option value="">기준 DB 선택</option>'+api.getLibraries().filter(l=>!isAssemblyPriceReference(l)).map(l=>`<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('');const lib=resourceLibrary(draft,api.getLibraries());if(lib)$('resourcePricesLibrary').value=lib.id;preview();$('resourcePricesDialog').showModal();}
 $('resourcePricesBtn').onclick=open;return {open};
}
